import numpy as np

class FractalValley:
    def __init__(self, dim=5):
        self.dim = dim
        # Parameters for the Weierstrass function components
        self.a = 0.5
        self.b = 2.0
        self.k_max = 20
        # Global minimum location
        self.global_min = np.zeros(dim)

    def weierstrass(self, x):
        """Helper function to compute the Weierstrass component"""
        terms = np.zeros_like(x)
        for k in range(self.k_max):
            terms += (self.a**k) * np.cos(2 * np.pi * (self.b**k) * x)
        return terms.sum()

    def f(self, x):
        # Base fractal component
        fractal_part = self.weierstrass(x)

        # Global basin with non-homogeneous width
        distance = np.linalg.norm(x - self.global_min)
        global_basin = 100 * (1 - np.exp(-0.1 * distance**2))

        # Local minima with varying sharpness
        local_peaks = np.zeros_like(x)
        for i in range(self.dim):
            local_peaks += 5 * np.sin(10 * x[i]) * np.exp(-0.5 * x[i]**2)

        # Combine components with different weights
        return (fractal_part**2 + global_basin + local_peaks).sum()

    def global_optimum(self):
        return 0.0
